window.RANKING=[{"law":"lpac","art":"47","t":"Artículo 47. Nulidad de pleno derecho.","mat":"Nulidad de pleno derecho","cl":"Lesionen derechos susceptibles de amparo; órgano manifiestamente incompetente por materia o territorio; contenido imposible; constitutivos de infracción penal; prescindiendo total y absolutamente del procedimiento o de las normas de órganos colegiados; facultades sin requisitos esenciales; otros por ley. Disposiciones nulas (47.2).","note":"Nulidad = «DOCE PEO»: Derechos de amparo · Órgano manifiestamente incompetente por MATERIA o TERRITORIO (¡jerarquía NO, eso es anulable!) · Contenido imposible · Delito · Prescindir TOTAL y absolutamente del procedimiento · Facultades sin requisitos Esenciales · Otros por Ley. Las disposiciones (47.2) también son nulas si vulneran la CE, leyes o normas superiores, regulan materias reservadas a ley o establecen retroactividad sancionadora desfavorable.","pr":"A","n":17,"ex":15,"sub":0},{"law":"escv","art":"29","t":"Artículo 29.","mat":"Consell","cl":"Órgano colegiado; potestad ejecutiva y reglamentaria; sede en Valencia.","note":"Consell: órgano colegiado de gobierno con potestad EJECUTIVA y REGLAMENTARIA; consellers nombrados por el President; sede en Valencia, pero sus servicios pueden descentralizarse por todo el territorio.","pr":"A","n":12,"ex":7,"sub":11},{"law":"lpac","art":"53","t":"Artículo 53. Derechos del interesado en el procedimiento administrativo.","mat":"Derechos del interesado en el procedimiento","cl":"Conocer el estado de tramitación, sentido del silencio, órgano y actos; identificar autoridades; no presentar documentos no exigidos o ya aportados; alegar y aportar documentos en cualquier momento anterior a la audiencia; obtener información; asistencia de asesor; cumplir obligaciones de pago por medios electrónicos. Sancionadores: notificación de hechos e infracciones y presunción de no existencia de responsabilidad.","note":"Interesado «CO-ID-NO-AL-AS-PA»: COnocer el estado · IDentificar autoridades · NO aportar lo ya entregado · ALegar antes de la audiencia · ASesor · PAgar electrónicamente. En sancionadores, además: saber de qué le acusan y PRESUNCIÓN de inocencia («no existencia de responsabilidad»).","pr":"A","n":13,"ex":11,"sub":4},{"law":"lpac","art":"39","t":"Artículo 39. Efectos.","mat":"Efectos","cl":"Válidos y eficaces desde la fecha en que se dicten salvo otra cosa. Eficacia demorada (notificación, publicación, aprobación superior). Retroactividad excepcional: sustitución de actos anulados y efectos favorables sin lesionar a terceros.","note":"Efectos: desde que se DICTAN (salvo que se disponga otra cosa). Eficacia demorada por notificación, publicación o aprobación superior. Retroactividad EXCEPCIONAL: en sustitución de actos ANULADOS o con efectos FAVORABLES, si los hechos ya existían y no se lesiona a terceros.","pr":"A","n":13,"ex":11,"sub":4},{"law":"lpac","art":"35","t":"Artículo 35. Motivación.","mat":"Motivación","cl":"Con sucinta referencia de hechos y fundamentos: actos que limiten derechos; resuelvan revisión de oficio, recursos, reclamaciones y arbitraje; se separen del criterio seguido o del dictamen; suspensión y medidas provisionales; urgencia, ampliación y actuaciones complementarias; rechazo de pruebas; terminación por imposibilidad y desistimiento de oficio; propuestas sancionadoras y de responsabilidad; discrecionales. Selectivos y concurrencia: según las bases.","note":"Motivación: «LiReSeSuUrPruTerPro…» → Limiten derechos · Resuelvan revisión de oficio, recursos y arbitraje · Se Separen del criterio precedente · Suspensión y medidas provisionales · Urgencia, ampliación y actuaciones complementarias · Rechacen Pruebas · Terminación por imposibilidad y desistimiento de la Administración · Propuestas en procedimientos sancionadores y de responsabilidad · potestades discrecionales.","pr":"A","n":15,"ex":15,"sub":2},{"law":"lbrl","art":"20","t":"Artículo 20.","mat":"Organización municipal","cl":"Alcalde, Tenientes y Pleno en todos; JGL en más de 5.000 o si se acuerda.","note":"Existen en todos los municipios: Alcalde, Tenientes de Alcalde, Pleno y Comisión Especial de Cuentas. JGL en los de >5.000 (o si lo decide el ROM o el Pleno).","pr":"A","n":16,"ex":12,"sub":1},{"law":"lpac","art":"43","t":"Artículo 43. Práctica de las notificaciones a través de medios electrónicos.","mat":"Notificaciones electrónicas","cl":"Por comparecencia en la sede o en la dirección electrónica habilitada única. Practicada al acceder a su contenido. Rechazada a los 10 días NATURALES sin acceder. El aviso no es requisito de validez.","note":"Notificación electrónica: se practica por comparecencia en la sede o en la DEHú. Se entiende practicada al ACCEDER. Rechazada a los 10 días NATURALES sin acceso. El aviso al correo es informativo: su falta NO invalida la notificación.","pr":"A","n":13,"ex":12,"sub":2},{"law":"lpac","art":"41","t":"Artículo 41. Condiciones generales para la práctica de las notificaciones.","mat":"Condiciones generales de las notificaciones","cl":"Preferentemente electrónicas. En papel: comparecencia espontánea en oficina de asistencia o entrega directa por empleado público. Medios de pago nunca electrónicos. Rechazo: se tiene por efectuado el trámite. Varios cauces: vale la primera.","note":"Notificaciones: preferentemente electrónicas. En papel solo con comparecencia espontánea en la oficina de asistencia o con entrega directa por un empleado público. Medios de pago (cheques) NUNCA por vía electrónica. Rechazo = se tiene por efectuada. Si se notifica por varios cauces vale la PRIMERA.","pr":"A","n":14,"ex":12,"sub":1},{"law":"lbrl","art":"26","t":"Artículo 26.","mat":"Servicios mínimos","cl":"Todos / más de 5.000 / más de 20.000 / más de 50.000. Muy preguntado.","note":"Servicios mínimos en 4 escalones: TODOS (alumbrado, cementerio, recogida de residuos, limpieza viaria, agua, alcantarillado, acceso, pavimentación); >5.000 «PaBiTra» (parque, biblioteca, tratamiento de residuos); >20.000 «ProSoInDe» (protección civil, servicios sociales, incendios, deportes); >50.000 «TraMa» (transporte urbano, medio ambiente urbano). La Diputación coordina en municipios de <20.000.","pr":"A","n":12,"ex":10,"sub":1},{"law":"ce","art":"1","t":"Artículo 1","mat":"Valores superiores y forma política","cl":"4 valores: libertad, justicia, igualdad, pluralismo político. Soberanía en el pueblo. Monarquía parlamentaria.","note":"Valores superiores «LIJUIGPO»: LIbertad, JUsticia, IGualdad, Pluralismo pOlítico. Soberanía en el pueblo español. Monarquía parlamentaria.","pr":"A","n":10,"ex":10,"sub":3},{"law":"lprevencion","art":"14","t":"Artículo 14. Derecho a la protección frente a los riesgos laborales.","mat":"Derecho a la protección","cl":"Protección eficaz; deber del empresario y de las AA. PP.","note":"Derecho a la protección eficaz = deber del empresario (y de las Administraciones con su personal). Comprende «IN-CON-PAR-FOR-PARALIZ-VIGIL»: INformación, CONsulta, PARticipación, FORmación, PARALIZación ante riesgo grave e inminente y VIGILancia de la salud. Su coste no recae nunca en los trabajadores.","pr":"A","n":9,"ex":9,"sub":3},{"law":"ce","art":"149","t":"Artículo 149","mat":"Competencias del Estado","cl":"Lista exclusiva; cláusula residual; prevalencia y supletoriedad (149.3).","note":"Competencias exclusivas del Estado: 32 materias. Trucos: lo «básico» y la «legislación» suelen ser del Estado (legislación laboral, mercantil, penal, procesal, civil con matices) y la «ejecución» de la CA. Las cláusulas residuales del 149.3 favorecen al Estado.","pr":"A","n":12,"ex":11,"sub":0},{"law":"lpac","art":"42","t":"Artículo 42. Práctica de las notificaciones en papel.","mat":"Notificaciones en papel","cl":"Si no está el interesado: cualquier persona mayor de 14 años que se encuentre en el domicilio y haga constar su identidad. Si nadie se hace cargo: segundo intento dentro de los 3 días siguientes, en hora distinta (margen de 3 horas antes/después de las 15 h).","note":"Notificación en papel «14-3-15-3»: puede recogerla un mayor de 14 años que esté en el domicilio; segundo intento UNA sola vez, dentro de los 3 días siguientes, a distinta hora (si el primero fue antes de las 15 h, el segundo después, y viceversa, con al menos 3 horas de diferencia).","pr":"A","n":9,"ex":8,"sub":2},{"law":"lbrl","art":"16","t":"Artículo 16.","mat":"Padrón","cl":"Prueba de residencia y domicilio; documento público y fehaciente; renovación cada 2 años (extranjeros no comunitarios sin autorización de residencia permanente).","note":"⚠ Artículo modificado (21/12/2023): comprueba el texto vigente. Padrón: prueba de residencia y domicilio. Extranjeros no comunitarios sin residencia de larga duración: renovación cada 2 AÑOS.","pr":"A","n":9,"ex":8,"sub":2},{"law":"ce","art":"17","t":"Artículo 17","mat":"Libertad personal","cl":"Detención preventiva: máximo 72 horas. Habeas corpus.","note":"Detención preventiva «72 horas máximo» (no más de lo estrictamente necesario). Derechos del detenido: informado de forma inmediata y comprensible, no declarar, abogado. Habeas corpus = puesta inmediata a disposición judicial. Prisión provisional: plazo máximo por ley.","pr":"A","n":8,"ex":8,"sub":3},{"law":"ce","art":"54","t":"Artículo 54","mat":"Defensor del Pueblo","cl":"Alto comisionado de las Cortes; designado por ellas; ley orgánica.","note":"Defensor del Pueblo: «Alto comisionado de las CORTES», designado por ellas, para defender el Título I; supervisa la actividad de la Administración; regulado por LO (LO 3/1981). Mandato de 5 años.","pr":"A","n":9,"ex":9,"sub":2},{"law":"lbrl","art":"21","t":"Artículo 21.","mat":"Alcalde","cl":"Atribuciones 21.1; indelegables 21.3; voto de calidad; bandos.","note":"Alcalde: atribuciones residuales. INDELEGABLES «COPRO-JE-SE-UR-PLA»: convocar y presidir, decidir empates, jefatura de personal (separación y despido), medidas urgentes en catástrofes, PLAntillas… Delegables en la JGL o los Tenientes de Alcalde: el resto. Operaciones de crédito previstas en el Presupuesto hasta el 10 % de los recursos ordinarios (las de tesorería, hasta el 15 %).","pr":"A","n":9,"ex":9,"sub":1},{"law":"lpac","art":"40","t":"Artículo 40. Notificación.","mat":"Notificación","cl":"Se notifican las resoluciones y actos que afecten a derechos e intereses, en 10 días desde que se dictan, con texto íntegro, si pone fin a la vía administrativa, recursos, órgano y plazo. Notificación defectuosa: efectos desde que el interesado se da por enterado. Basta el intento con texto íntegro para cumplir el plazo máximo.","note":"Notificación «10 días»: se cursa dentro de los 10 días desde que se dicta el acto. Contiene el texto íntegro, si pone fin a la vía administrativa, los recursos, el órgano y el plazo. Notificación defectuosa = efectos desde que el interesado se da por enterado. Para cumplir el plazo de resolver basta el INTENTO de notificación debidamente acreditado.","pr":"A","n":9,"ex":9,"sub":1},{"law":"ce","art":"140","t":"Artículo 140","mat":"Municipio","cl":"Autonomía; personalidad jurídica plena; concejales por sufragio; concejo abierto.","note":"Municipio: autonomía garantizada y personalidad jurídica PLENA (la provincia, PROPIA: art. 141). Concejales elegidos por sufragio universal, igual, libre, directo y secreto; el Alcalde, por los concejales o por los vecinos. La ley regula el concejo abierto.","pr":"A","n":8,"ex":7,"sub":2},{"law":"lpac","art":"107","t":"Artículo 107. Declaración de lesividad de actos anulables.","mat":"Declaración de lesividad","cl":"Actos favorables anulables: declaración de lesividad para impugnarlos en el contencioso. Dentro de 4 años; audiencia; 6 meses o caducidad. No recurrible. Entidades locales: el Pleno o el órgano colegiado superior.","note":"Lesividad «4-6-NR»: solo para actos FAVORABLES y ANULABLES. Plazo de 4 años desde que se dictó; caducidad a los 6 meses desde la iniciación; la declaración No es Recurrible. Exige audiencia previa. En entidades locales la declara el PLENO (o el órgano colegiado superior).","pr":"A","n":10,"ex":10,"sub":0},{"law":"escv","art":"23","t":"Artículo 23.","mat":"Composición de Les Corts","cl":"No menos de 99 diputados.","note":"Les Corts: «99 = mínimo». Las integran no menos de 99 diputados y diputadas, elegidos por sufragio universal, igual, libre, directo y secreto.","pr":"A","n":8,"ex":8,"sub":4},{"law":"escv","art":"27","t":"Artículo 27.","mat":"President","cl":"Elegido por Les Corts de entre sus miembros y nombrado por el Rey; mayoría absoluta en 1.ª votación.","note":"President: elegido por Les Corts de ENTRE SUS MIEMBROS y nombrado por el Rey. Los candidatos los presentan los Grupos Parlamentarios y el Presidente de Les Corts propone uno tras consultar. El candidato expone su programa y pide la confianza.","pr":"A","n":7,"ex":7,"sub":3},{"law":"lpac","art":"125","t":"Artículo 125. Objeto y plazos.","mat":"Recurso extraordinario de revisión: objeto y plazos","cl":"Contra actos firmes, ante el mismo órgano: error de hecho que resulte de documentos del expediente (4 años desde la notificación); documentos de valor esencial; documentos o testimonios declarados falsos por sentencia firme; prevaricación, cohecho, violencia u otra conducta punible por sentencia firme (3 meses).","note":"Recurso extraordinario de revisión «E-D-F-P»: Error de hecho (4 años), Documentos esenciales nuevos, Falsedad declarada en sentencia, Prevaricación o cohecho declarados en sentencia (en estos tres, 3 meses desde el conocimiento o la firmeza). Solo contra actos FIRMES y ante el mismo órgano.","pr":"A","n":9,"ex":9,"sub":0},{"law":"ce","art":"137","t":"Artículo 137","mat":"Organización territorial","cl":"Municipios, provincias y CCAA; autonomía para sus intereses.","note":"Estado territorial «MPCA»: Municipios, Provincias y Comunidades Autónomas, todas con autonomía para la gestión de SUS intereses.","pr":"A","n":9,"ex":9,"sub":0},{"law":"lpac","art":"52","t":"Artículo 52. Convalidación.","mat":"Convalidación","cl":"La Administración puede convalidar los actos ANULABLES subsanando los vicios. Efecto desde la fecha de la convalidación (salvo retroactividad del 39.3). Incompetencia no determinante de nulidad: la convalida el superior jerárquico; falta de autorización: otorgándola.","note":"Convalidación: solo actos ANULABLES. Produce efecto desde su fecha (salvo la retroactividad del 39.3). Incompetencia no determinante de nulidad: la convalida el superior jerárquico. Falta de autorización: se convalida otorgándola.","pr":"A","n":9,"ex":9,"sub":0},{"law":"lpac","art":"96","t":"Artículo 96. Tramitación simplificada del procedimiento administrativo común.","mat":"Tramitación simplificada","cl":"De oficio o a solicitud, por interés público o falta de complejidad. Si un interesado se opone expresamente: ordinaria. Resolución en 30 días. Trámites limitados. Sancionador: infracción leve.","note":"Tramitación simplificada: se resuelve en 30 DÍAS. Oposición expresa de un interesado = ordinaria. Solicitud desestimable en 5 días sin recurso. En sanciones, cuando la infracción es LEVE.","pr":"A","n":9,"ex":8,"sub":0},{"law":"lpac","art":"112","t":"Artículo 112. Objeto y clases.","mat":"Objeto y clases de recursos","cl":"Contra resoluciones y actos de trámite cualificados (deciden el fondo, imposibilitan continuar, producen indefensión o perjuicio irreparable): alzada y reposición potestativo. Fundados en nulidad o anulabilidad. Contra disposiciones generales no cabe recurso administrativo. Procedimientos sustitutivos por ley.","note":"Recursos: alzada o reposición contra resoluciones y actos de trámite cualificados («DIIP»: Deciden el fondo, Imposibilitan continuar, Indefensión, Perjuicio irreparable). Contra disposiciones generales NO cabe recurso administrativo.","pr":"A","n":9,"ex":8,"sub":0},{"law":"ce","art":"14","t":"Artículo 14","mat":"Igualdad","cl":"Nacimiento, raza, sexo, religión, opinión u otra circunstancia. Se refiere a los «españoles».","note":"Igualdad ante la ley, sin discriminación por «NARASEREOP»: NAcimiento, RAza, SExo, RElig., OPinión o cualquier otra condición o circunstancia personal o social. Es amparable.","pr":"A","n":7,"ex":6,"sub":2},{"law":"lpac","art":"81","t":"Artículo 81. Solicitud de informes y dictámenes en los procedimientos de responsabilidad patrimonial.","mat":"Informes en responsabilidad patrimonial","cl":"Informe del servicio cuyo funcionamiento causó la lesión (10 días). Dictamen del Consejo de Estado u órgano consultivo autonómico cuando la cuantía sea igual o superior a 50.000 euros (o lo que fije la CCAA); dictamen en 2 meses.","note":"Responsabilidad patrimonial «10-50-2»: informe del servicio en 10 días; dictamen del Consejo de Estado u órgano autonómico si la cuantía es ≥ 50.000 €; el dictamen se emite en 2 meses. El instructor remite la propuesta en 10 días desde el fin de la audiencia.","pr":"A","n":8,"ex":7,"sub":0},{"law":"lpac","art":"45","t":"Artículo 45. Publicación.","mat":"Publicación","cl":"Cuando lo establezcan las normas o lo aconsejen razones de interés público; destinatarios indeterminados; procedimientos selectivos o de concurrencia competitiva (indicando el tablón o medio). Efectos de la notificación.","note":"Publicación en lugar de notificación «IN-SE»: destinatarios INdeterminados o acto que ponga fin a un procedimiento SElectivo o de concurrencia competitiva. Produce los efectos de la notificación.","pr":"A","n":7,"ex":7,"sub":2},{"law":"lpac","art":"36","t":"Artículo 36. Forma.","mat":"Forma","cl":"Por escrito y por medios electrónicos salvo que exijan otra forma. Actos verbales: constancia escrita (la hace el titular inferior o el funcionario que los recibe). Actos de la misma naturaleza: una sola resolución.","note":"Forma: ESCRITA y ELECTRÓNICA. Si el acto es verbal y hace falta constancia, la firma el titular del órgano INFERIOR o el funcionario que lo recibe oralmente, indicando la autoridad de la que procede.","pr":"A","n":9,"ex":9,"sub":4},{"law":"lo3","art":"3","t":"Artículo 3. El principio de igualdad de trato entre mujeres y hombres.","mat":"Igualdad de trato","cl":"Ausencia de discriminación directa o indirecta.","note":"Igualdad de trato = AUSENCIA de toda discriminación directa o indirecta por razón de sexo, especialmente por «MA-FA-CI»: MAternidad, obligaciones FAmiliares y estado CIvil.","pr":"A","n":5,"ex":5,"sub":4},{"law":"lpac","art":"82","t":"Artículo 82. Trámite de audiencia.","mat":"Trámite de audiencia","cl":"Instruido el procedimiento e inmediatamente antes de la propuesta de resolución; plazo no inferior a 10 días ni superior a 15. Se puede prescindir si no figuran ni se tienen en cuenta otros hechos, alegaciones o pruebas que las del interesado.","note":"Audiencia «10-15»: entre 10 y 15 días, inmediatamente ANTES de la propuesta de resolución y antes del informe jurídico o del dictamen. Se puede prescindir si solo constan los hechos y alegaciones del propio interesado.","pr":"A","n":7,"ex":7,"sub":0},{"law":"lbrl","art":"15","t":"Artículo 15.","mat":"Empadronamiento","cl":"Obligación; quien viva en varios: donde habite más tiempo; vecino desde la inscripción.","note":"Padrón: obligatorio inscribirse donde se reside habitualmente (si son varios, donde más tiempo se vive). Vecino desde la inscripción.","pr":"A","n":7,"ex":7,"sub":0},{"law":"lpac","art":"88","t":"Artículo 88. Contenido.","mat":"Contenido de la resolución","cl":"Decide todas las cuestiones planteadas y derivadas. A solicitud: congruente, sin agravar la situación inicial. Motivada (art. 35), expresa recursos, órgano y plazo. No se puede abstener de resolver por silencio u oscuridad de las normas.","note":"Resolución: TODAS las cuestiones; si el procedimiento es a solicitud, CONGRUENTE con lo pedido y SIN reformatio in peius. Nunca puede negarse a resolver alegando silencio, oscuridad o insuficiencia de la norma (sí puede inadmitir solicitudes de derechos no previstos o manifiestamente carentes de fundamento).","pr":"A","n":7,"ex":7,"sub":0},{"law":"rople","art":"22","t":"Artículo 22. Sesiones ordinarias.","mat":"Sesiones ordinarias del Pleno de Gandia","cl":"Mensuales; día y hora fijados por el Pleno en la sesión de organización (en el mandato 2023-2027, el tercer viernes de cada mes a las 10:00 h).","note":"«MES a MES»: tercer VIERNES a las 10:00. Lo fija el PLENO tras su constitución.","pr":"A","n":0,"ex":0,"sub":0},{"law":"rople","art":"26","t":"Artículo 26. De las sesiones ordinarias y extraordinarias a iniciativa de la presidencia.","mat":"Convocatoria y quórum de inicio","cl":"Única convocatoria salvo que se indique la segunda; a los 60 minutos sin quórum se deja sin efecto.","note":"«60 minutos de cortesía»: sin quórum, los asuntos pasan a la siguiente ORDINARIA.","pr":"A","n":0,"ex":0,"sub":0},{"law":"rople","art":"36","t":"Artículo 36. Asuntos de urgencia (mociones resolutivas).","mat":"Mociones de urgencia","cl":"Sólo en sesiones ordinarias; declaración de urgencia por mayoría absoluta.","note":"«Urgencia = sólo ORDINARIA + mayoría ABSOLUTA».","pr":"A","n":0,"ex":0,"sub":0},{"law":"rople","art":"46","t":"Artículo 46. Límites a la presentación de ruegos y preguntas.","mat":"Límite de ruegos y preguntas","cl":"Máximo 5 entre ruegos y preguntas por grupo y 1 por miembro no adscrito.","note":"«5 por GRUPO, 1 por NO ADSCRITO».","pr":"A","n":0,"ex":0,"sub":0},{"law":"rople","art":"62","t":"Artículo 62. Sistema de votación.","mat":"Sistema de votación","cl":"Ordinaria por regla general; nominal a petición aprobada por mayoría simple; secreta para la elección de la Alcaldía.","note":"«Ordinaria normal, Nominal si se pide (simple), Secreta para el ALCALDE».","pr":"A","n":0,"ex":0,"sub":0},{"law":"rople","art":"73","t":"Artículo 73. Constitución válida de la sesión.","mat":"Quórum de las comisiones del Pleno","cl":"Un tercio del número legal, nunca menos de tres, con presidencia y secretaría.","note":"«Comisión: 1/3 y mínimo 3» (igual que el Pleno en la LBRL).","pr":"A","n":0,"ex":0,"sub":0},{"law":"roga","art":"17","t":"Artículo 17. Composición y nombramiento.","mat":"Composición de la Junta de Gobierno de la Ciudad","cl":"Máximo un tercio del número legal del Pleno, además del Alcalde; no concejales hasta un tercio; Concejal Secretario.","note":"«1/3 + Alcalde; NO concejales ≤ 1/3». En Gandia: Alcalde + 8.","pr":"A","n":0,"ex":0,"sub":0},{"law":"roga","art":"20","t":"Artículo 20. Sesiones de la Junta de Gobierno.","mat":"Sesiones y quórum de la Junta de Gobierno","cl":"Convocatoria con 24 h; Alcalde, Concejal Secretario y la mitad de los miembros; concejales presentes más que no concejales.","note":"«24 h, MITAD y más CONCEJALES que externos». Ordinarias: lunes a las 10:30.","pr":"A","n":0,"ex":0,"sub":0},{"law":"roga","art":"22","t":"Artículo 22. Deliberaciones.","mat":"Deliberaciones secretas","cl":"Las deliberaciones son secretas y los asistentes guardan secreto.","note":"«La JGL delibera en SECRETO (el Pleno, en público)».","pr":"A","n":0,"ex":0,"sub":0},{"law":"roga","art":"25","t":"Artículo 25. Forma de los acuerdos.","mat":"Forma y firma de los acuerdos","cl":"«Acuerdos de la Junta de Gobierno de la Ciudad de Gandia», firmados por el Alcalde y el Concejal Secretario.","note":"«Firman DOS: Alcalde + Concejal Secretario; certifica UNO: el Concejal Secretario».","pr":"A","n":0,"ex":0,"sub":0},{"law":"postal","art":"22","t":"Artículo 22. Principios y requisitos de la prestación del servicio postal universal.","mat":"Principios del servicio postal universal","cl":"Equidad, no discriminación, continuidad, buena fe y adaptación.","note":"«E-N-C-B-A»: Equidad, No discriminación, Continuidad, Buena fe, Adaptación.","pr":"A","n":0,"ex":0,"sub":0},{"law":"rd203","art":"7","t":"Artículo 7. Punto de Acceso General electrónico.","mat":"Punto de Acceso General electrónico","cl":"Cada Administración tiene un PAGe; el de la AGE es administracion.gob.es.","note":"«PAGe = la PUERTA general»; dentro, la Carpeta Ciudadana (art. 8).","pr":"A","n":0,"ex":0,"sub":0},{"law":"lbrl","art":"121","t":"Artículo 121. Ámbito de aplicación.","mat":"Ámbito del régimen de gran población","cl":"Más de 250.000 habitantes, capitales de provincia de más de 175.000, capitales autonómicas y, por ley autonómica, municipios de más de 75.000.","note":"Gandia entra por la Ley 5/2010 de Les Corts.","pr":"A","n":1,"ex":1,"sub":0},{"law":"lpac","art":"95","t":"Artículo 95. Requisitos y efectos.","mat":"Caducidad","cl":"A solicitud, paralizado por causa del interesado: aviso y a los 3 meses caducidad y archivo. No caduca si es trámite no indispensable. No produce por sí sola la prescripción, pero los procedimientos caducados no la interrumpen. Se pueden conservar actos en el nuevo procedimiento.","note":"Caducidad por culpa del interesado: «AVISO + 3 MESES» → archivo. La caducidad no extingue la acción, pero el procedimiento caducado NO interrumpe la prescripción. No cabe si se trata de un trámite NO indispensable.","pr":"B","n":7,"ex":7,"sub":0},{"law":"lpac","art":"68","t":"Artículo 68. Subsanación y mejora de la solicitud.","mat":"Subsanación y mejora de la solicitud","cl":"10 días para subsanar; si no, desistido previa resolución. Ampliable hasta 5 días más (no en selectivos ni concurrencia competitiva). Presentación presencial de obligados: subsanar por vía electrónica.","note":"Subsanación: «10 + 5» días (los 5 de ampliación NO en selectivos ni concurrencia competitiva). Si no se subsana = DESISTIDO, previa resolución. Si un obligado presenta en papel: se le requiere subsanar electrónicamente y la fecha válida es la de la subsanación.","pr":"B","n":7,"ex":7,"sub":0},{"law":"lprevencion","art":"22","t":"Artículo 22. Vigilancia de la salud.","mat":"Vigilancia de la salud","cl":"Voluntaria, con excepciones tasadas; consentimiento.","note":"Vigilancia de la salud: «Voluntaria, salvo 3 excepciones»: cuando sea imprescindible evaluar los efectos de las condiciones de trabajo, verificar si el estado del trabajador es un peligro para él o para otros, o lo disponga una ley. Datos confidenciales: el empresario solo recibe las conclusiones de aptitud.","pr":"B","n":6,"ex":6,"sub":3},{"law":"lbrl","art":"25","t":"Artículo 25.","mat":"Competencias propias","cl":"Lista 25.2.","note":"⚠ Artículo modificado (23/10/2026): comprueba el texto vigente. Competencias propias (25.2): ¡las de cada día en el pueblo! Urbanismo, medio ambiente urbano, agua, infraestructura viaria, policía local, tráfico, protección civil, residuos, cementerios, mercados, transporte urbano, cultura, deporte, turismo, ferias, servicios sociales (atención inmediata), vigilancia de la escolaridad. Siempre determinadas por LEY.","pr":"B","n":7,"ex":7,"sub":0},{"law":"lprevencion","art":"29","t":"Artículo 29. Obligaciones de los trabajadores en materia de prevención de riesgos.","mat":"Obligaciones de los trabajadores","cl":"Uso adecuado, informar, cooperar.","note":"Obligaciones del trabajador «U-U-NO-I-C-C»: Usar bien las máquinas, Usar los EPI, NO desactivar los dispositivos de seguridad, Informar de los riesgos, Contribuir al cumplimiento, Cooperar con el empresario. Incumplir = incumplimiento laboral (o falta disciplinaria si es funcionario).","pr":"B","n":4,"ex":4,"sub":3},{"law":"lbrl","art":"23","t":"Artículo 23.","mat":"Junta de Gobierno Local","cl":"Alcalde + hasta 1/3 de concejales; Tenientes.","note":"Junta de Gobierno: Alcalde + concejales ≤ 1/3 del número legal, nombrados y separados LIBREMENTE por el Alcalde (dando cuenta al Pleno). Funciones: asistir al Alcalde y las atribuciones delegadas o legales. Tenientes de Alcalde: los nombra el Alcalde de entre los miembros de la JGL y sustituyen por orden de nombramiento.","pr":"B","n":7,"ex":7,"sub":0},{"law":"lpac","art":"48","t":"Artículo 48. Anulabilidad.","mat":"Anulabilidad","cl":"Cualquier infracción del ordenamiento, incluso la desviación de poder. Defecto de forma: solo si falta un requisito indispensable para el fin o causa indefensión. Fuera de plazo: solo si lo impone la naturaleza del término.","note":"Anulabilidad: cualquier infracción, INCLUIDA la desviación de poder. El defecto de forma solo si impide el fin o causa indefensión. La actuación fuera de plazo solo si lo impone la naturaleza del plazo.","pr":"B","n":6,"ex":6,"sub":0},{"law":"lpac","art":"56","t":"Artículo 56. Medidas provisionales.","mat":"Medidas provisionales","cl":"Iniciado el procedimiento: las adopta el órgano competente para resolver si hay elementos de juicio. Antes de iniciarlo: urgencia inaplazable; confirmación, modificación o levantamiento en el acuerdo de iniciación en 15 días. Proporcionalidad, efectividad y menor onerosidad.","note":"Medidas provisionales «PEMO»: Proporcionalidad, Efectividad y Menor Onerosidad. Antes de iniciarse el procedimiento, solo por urgencia inaplazable, y el acuerdo de iniciación debe confirmarlas en 15 días (si no, quedan sin efecto).","pr":"B","n":6,"ex":6,"sub":0},{"law":"lpac","art":"67","t":"Artículo 67. Solicitudes de iniciación en los procedimientos de responsabilidad patrimonial.","mat":"Solicitudes de responsabilidad patrimonial","cl":"Derecho a reclamar prescribe al año del hecho o de la manifestación del efecto lesivo; daños físicos o psíquicos: desde la curación o determinación del alcance de las secuelas. Anulación de acto: un año desde la notificación de la sentencia.","note":"Responsabilidad patrimonial: reclamar en 1 AÑO. Daños físicos o psíquicos: el año empieza con la CURACIÓN o la fijación de secuelas. Si el daño viene de un acto anulado, 1 año desde la sentencia definitiva.","pr":"B","n":6,"ex":6,"sub":0},{"law":"lpac","art":"77","t":"Artículo 77. Medios y período de prueba.","mat":"Medios y período de prueba","cl":"Cualquier medio admisible en Derecho. Período de prueba no superior a 30 días ni inferior a 10. Extraordinario: no superior a 10 días. Rechazo motivado solo si son improcedentes o innecesarias.","note":"⚠ Artículo modificado (14/07/2022): comprueba el texto vigente. Prueba «10-30 + 10»: período ordinario entre 10 y 30 días; extraordinario hasta 10 días. Rechazo de pruebas: resolución MOTIVADA. Los hechos de sentencias penales firmes vinculan.","pr":"B","n":6,"ex":6,"sub":0},{"law":"lpac","art":"114","t":"Artículo 114. Fin de la vía administrativa.","mat":"Fin de la vía administrativa","cl":"Resoluciones de alzada; procedimientos sustitutivos; órganos sin superior jerárquico salvo ley; demás resoluciones cuando una disposición lo establezca; acuerdos finalizadores; responsabilidad patrimonial; sancionadores en que el recurso no sea posible; en la AGE, Ministros, Secretarios de Estado, etc.","note":"Ponen fin a la vía administrativa: resolución de ALZADA · procedimientos SUSTITUTIVOS · órgano SIN superior jerárquico · lo que diga una norma · acuerdos finalizadores · resolución de RESPONSABILIDAD PATRIMONIAL · procedimiento complementario de indemnización en sancionadores. En el Ayuntamiento: Alcalde y Pleno (art. 52 LBRL).","pr":"B","n":6,"ex":6,"sub":0},{"law":"lbrl","art":"11","t":"Artículo 11.","mat":"Municipio","cl":"Entidad local básica; elementos: territorio, población, organización.","note":"Municipio = entidad local básica de la organización territorial del Estado. Elementos «TPO»: Territorio, Población y Organización. Personalidad jurídica y plena capacidad.","pr":"B","n":5,"ex":5,"sub":1},{"law":"escv","art":"3","t":"Artículo 3.","mat":"Condición política de valenciano","cl":"Vecindad administrativa en un municipio de la CV.","note":"Condición política de valenciano: españoles con VECINDAD ADMINISTRATIVA en cualquier municipio de la Comunitat. Los residentes en el extranjero, si su última vecindad fue aquí y lo acreditan en el Consulado (también sus descendientes, si lo solicitan).","pr":"B","n":5,"ex":5,"sub":2},{"law":"ce","art":"148","t":"Artículo 148","mat":"Competencias que pueden asumir las CCAA","cl":"Lista del art. 148 (autogobierno, urbanismo, agricultura, turismo, deporte, asistencia social…); el 149 son las exclusivas del Estado.","note":"«148 = lo que PUEDEN coger las CCAA; 149 = lo que el Estado se QUEDA». Truco: 148 empieza por «organización de sus instituciones de autogobierno». Pasados 5 años pueden ampliar competencias reformando el Estatuto (148.2).","pr":"B","n":5,"ex":5,"sub":1},{"law":"escv","art":"39","t":"Artículo 39. La Sindicatura de Comptes.","mat":"Sindicatura de Comptes","cl":"Control externo económico y presupuestario.","note":"⚠ Artículo modificado (recientemente): comprueba el texto vigente. Sindicatura de Comptes = el «Tribunal de Cuentas valenciano»: control externo económico y presupuestario de la Generalitat, entes locales y sector público valenciano; depende orgánicamente de Les Corts.","pr":"B","n":5,"ex":5,"sub":1},{"law":"escv","art":"21","t":"Artículo 21.","mat":"Les Corts","cl":"Potestad legislativa; inviolables; sede en el Palacio de los Borja.","note":"Les Corts: potestad legislativa; representan al pueblo; son INVIOLABLES y gozan de autonomía. Sede: Palau dels BORJA (València), aunque pueden reunirse en otros lugares de la Comunitat.","pr":"B","n":3,"ex":3,"sub":3},{"law":"lprevencion","art":"15","t":"Artículo 15. Principios de la acción preventiva.","mat":"Principios de la acción preventiva","cl":"Evitar, evaluar, combatir en origen, adaptar, sustituir, planificar, protección colectiva.","note":"Principios de la acción preventiva: «EVITAR, EVALUAR, COMBATIR EN EL ORIGEN, ADAPTAR AL HOMBRE, TÉCNICA, SUSTITUIR, PLANIFICAR, COLECTIVO > INDIVIDUAL, INSTRUCCIONES». Regla de oro: primero se evita; lo que no se puede evitar, se evalúa; la protección colectiva va antes que la individual.","pr":"B","n":4,"ex":4,"sub":1},{"law":"lpac","art":"122","t":"Artículo 122. Plazos.","mat":"Recurso de alzada: plazos","cl":"Acto expreso: 1 mes. Si no es expreso: en cualquier momento desde el día siguiente al silencio. Resolución y notificación: 3 meses; silencio desestimatorio (salvo 24.1). Contra su resolución no cabe otro recurso administrativo salvo el extraordinario de revisión.","note":"Alzada «1-3»: 1 MES para interponer (sin plazo si no hay acto expreso), 3 MESES para resolver. Tras la alzada, solo el EXTRAORDINARIO de revisión.","pr":"B","n":5,"ex":5,"sub":0},{"law":"lpac","art":"84","t":"Artículo 84. Terminación.","mat":"Terminación","cl":"Resolución, desistimiento, renuncia y declaración de caducidad. Imposibilidad material de continuar por causas sobrevenidas: resolución motivada.","note":"Terminación «RE-DE-RE-CA»: REsolución, DEsistimiento, REnuncia, CAducidad + imposibilidad material sobrevenida (resolución motivada).","pr":"B","n":5,"ex":5,"sub":0},{"law":"lpac","art":"69","t":"Artículo 69. Declaración responsable y comunicación.","mat":"Declaración responsable y comunicación","cl":"Declaración responsable: el interesado manifiesta bajo su responsabilidad que cumple los requisitos y dispone de documentación. Comunicación: pone en conocimiento datos. Permiten el ejercicio desde su presentación. Inexactitud esencial: impide continuar.","note":"Declaración responsable = «CUMPLO y lo TENGO»; Comunicación = «te AVISO». Ambas habilitan desde el día de su PRESENTACIÓN. Falsedad o inexactitud ESENCIAL: cese de la actividad y posible imposibilidad de pedir lo mismo durante el tiempo que fije la ley.","pr":"B","n":5,"ex":5,"sub":0},{"law":"ce","art":"147","t":"Artículo 147","mat":"Estatutos","cl":"Norma institucional básica; contenido mínimo (147.2).","note":"Estatuto = norma institucional básica de la CA. Contenido mínimo «DeTeDeCo»: Denominación, Territorio, Denominación/organización/sede de las instituciones, Competencias. Reforma: lo que el propio Estatuto diga + ley orgánica de las Cortes.","pr":"B","n":4,"ex":4,"sub":1},{"law":"lpac","art":"37","t":"Artículo 37. Inderogabilidad singular.","mat":"Inderogabilidad singular","cl":"Las resoluciones de carácter particular no pueden vulnerar lo establecido en una disposición de carácter general, aunque procedan de un órgano de igual o superior jerarquía. Son nulas.","note":"«El jefe tampoco puede saltarse su propio reglamento»: una resolución particular que vulnera una disposición general es NULA, aunque la dicte el mismo órgano o uno superior.","pr":"B","n":5,"ex":5,"sub":0},{"law":"lpac","art":"106","t":"Artículo 106. Revisión de disposiciones y actos nulos.","mat":"Revisión de disposiciones y actos nulos","cl":"En cualquier momento, de oficio o a solicitud, actos firmes o que no se recurrieron en plazo, previo dictamen FAVORABLE del Consejo de Estado u órgano consultivo autonómico. Disposiciones: solo de oficio. Inadmisión sin dictamen. Plazo de 6 meses: caducidad (de oficio) o desestimación (a solicitud).","note":"Revisión de nulos «CUALQUIER MOMENTO + dictamen FAVORABLE + 6 MESES». De oficio y no resuelto en 6 meses: caducidad; a solicitud: desestimada. Disposiciones generales nulas: solo DE OFICIO.","pr":"B","n":5,"ex":5,"sub":0},{"law":"lbrl","art":"27","t":"Artículo 27.","mat":"Delegación de competencias en municipios","cl":"El Estado y las CCAA pueden delegar competencias en los municipios; mínimo 5 años; con financiación.","note":"Delegación «5-F»: duración mínima de 5 AÑOS y siempre con FINANCIACIÓN suficiente. La Administración que delega conserva la dirección y el control.","pr":"B","n":5,"ex":4,"sub":0},{"law":"lpac","art":"34","t":"Artículo 34. Producción y contenido.","mat":"Producción y contenido","cl":"Los actos se dictan por el órgano competente, ajustándose a los requisitos y al procedimiento; contenido ajustado al ordenamiento, determinado y adecuado a los fines.","note":"Elementos del acto: órgano COMPETENTE + PROCEDIMIENTO + contenido determinado y adecuado a los fines.","pr":"B","n":4,"ex":4,"sub":2},{"law":"lbrl","art":"18","t":"Artículo 18.","mat":"Derechos y deberes de los vecinos","cl":"Lista 18.1 a)–h).","note":"Derechos y deberes de los vecinos: elector y elegible; participar; usar los servicios y aprovechamientos comunales; CONTRIBUIR (deber); ser informado; pedir CONSULTA popular; exigir el servicio obligatorio; iniciativa popular.","pr":"B","n":5,"ex":5,"sub":0},{"law":"lbrl","art":"17","t":"Artículo 17.","mat":"Gestión del Padrón","cl":"Ayuntamiento; Diputaciones si no tienen capacidad; Consejo de Empadronamiento.","note":"⚠ Artículo modificado (21/12/2023): comprueba el texto vigente. Padrón = «lo hace el AYUNTAMIENTO, lo coordina el INE». Formación, mantenimiento, revisión y custodia: Ayuntamiento (Diputaciones si no puede). Discrepancias INE–Ayuntamiento → Consejo de Empadronamiento (adscrito al Ministerio, presidido por el Presidente del INE).","pr":"B","n":5,"ex":5,"sub":0},{"law":"escv","art":"6","t":"Artículo 6.","mat":"Lenguas","cl":"Lengua propia: valenciano; cooficial con el castellano; AVL como institución normativa (6.8).","note":"Lenguas: valenciano = lengua PROPIA; cooficial con el castellano; nadie puede ser discriminado por su lengua; especial protección a la recuperación del valenciano; AVL = institución normativa (6.8).","pr":"B","n":6,"ex":6,"sub":5},{"law":"ce","art":"22","t":"Artículo 22","mat":"Derecho de asociación","cl":"Asociaciones inscritas sólo a efectos de publicidad; prohibidas secretas y paramilitares; disolución sólo por resolución judicial motivada.","note":"«Inscribir = publicidad; disolver = juez». Prohibidas: SECRETAS y PARAMILITARES. Las que persigan fines o usen medios delictivos son ilegales.","pr":"B","n":3,"ex":3,"sub":2},{"law":"ce","art":"2","t":"Artículo 2","mat":"Unidad y autonomía","cl":"Indisoluble unidad; autonomía de nacionalidades y regiones; solidaridad.","note":"Art. 2 «U-A-S»: Unidad (indisoluble, patria común e indivisible), Autonomía (de nacionalidades y regiones) y Solidaridad entre todas ellas.","pr":"B","n":4,"ex":4,"sub":1},{"law":"ce","art":"27","t":"Artículo 27","mat":"Derecho a la educación y libertad de enseñanza","cl":"Enseñanza básica obligatoria y gratuita; libertad de creación de centros; autonomía universitaria.","note":"«Básica = Obligatoria + Gratuita (OG)». El art. 27 reconoce la LIBERTAD DE ENSEÑANZA; la libertad de cátedra está en el 20.1.c.","pr":"B","n":3,"ex":3,"sub":2},{"law":"ce","art":"145","t":"Artículo 145","mat":"Prohibición de federación de CCAA","cl":"En ningún caso se admite la federación de CCAA; convenios entre ellas con comunicación a las Cortes; acuerdos de cooperación con autorización de las Cortes.","note":"«Federarse NUNCA; convenios: avisan a las Cortes; cooperación: las Cortes autorizan».","pr":"B","n":4,"ex":4,"sub":1},{"law":"postal","art":"21","t":"Artículo 21. Ámbito.","mat":"Ámbito del servicio postal universal","cl":"Cartas y tarjetas hasta 2 kg; paquetes hasta 20 kg; certificado y valor declarado como accesorios.","note":"«2 y 20»: CARTAS hasta 2 kg, PAQUETES hasta 20 kg. Accesorios: CERTIFICADO y VALOR DECLARADO. Libros, catálogos y publicidad entran si van como carta o paquete.","pr":"B","n":3,"ex":2,"sub":3},{"law":"lprevencion","art":"20","t":"Artículo 20. Medidas de emergencia.","mat":"Medidas de emergencia","cl":"El empresario analiza las situaciones de emergencia y adopta medidas de primeros auxilios, lucha contra incendios y evacuación, designando personal.","note":"Emergencias «PIE»: Primeros auxilios, Incendios, Evacuación. El personal designado debe ser suficiente, formado y con material adecuado.","pr":"B","n":3,"ex":3,"sub":3},{"law":"escv","art":"43","t":"Artículo 43. El Consell Jurídic Consultiu.","mat":"Consell Jurídic Consultiu","cl":"Órgano consultivo supremo.","note":"Consell Jurídic Consultiu = el «Consejo de Estado valenciano»: órgano consultivo SUPREMO del Consell, de la Administración autonómica y, en su caso, de los entes locales, en materia jurídica.","pr":"B","n":3,"ex":3,"sub":2},{"law":"lpac","art":"116","t":"Artículo 116. Causas de inadmisión.","mat":"Causas de inadmisión","cl":"Órgano incompetente (se remite al competente); falta de legitimación; acto no recurrible; plazo transcurrido; carencia manifiesta de fundamento.","note":"Inadmisión «IN-LE-NO-PLA-FU»: INcompetencia · falta de LEgitimación · acto NO recurrible · PLAzo pasado · sin FUndamento manifiesto.","pr":"B","n":4,"ex":4,"sub":0},{"law":"lpac","art":"51","t":"Artículo 51. Conservación de actos y trámites.","mat":"Conservación de actos y trámites","cl":"El órgano que declare la nulidad o anule dispondrá la conservación de actos y trámites cuyo contenido se habría mantenido igual sin la infracción.","note":"Conservación: lo que habría salido igual sin el vicio, SE CONSERVA.","pr":"B","n":4,"ex":4,"sub":0},{"law":"lpac","art":"73","t":"Artículo 73. Cumplimiento de trámites.","mat":"Cumplimiento de trámites","cl":"Trámites de los interesados: 10 días desde la notificación salvo otro plazo. Defectos: requerimiento con 10 días. Fuera de plazo: se admite si se cumple antes o dentro del día en que se notifica la resolución que tiene por transcurrido el plazo.","note":"Trámites del interesado: 10 días. Si no los cumple, se le puede declarar DECAÍDO en su derecho, pero se admite su actuación si la hace ANTES o DENTRO del día en que se le notifica esa resolución.","pr":"B","n":4,"ex":4,"sub":0},{"law":"lpac","art":"80","t":"Artículo 80. Emisión de informes.","mat":"Emisión de informes","cl":"Facultativos y no vinculantes salvo disposición. Electrónicos. Plazo de 10 días. Si no se emite: se pueden proseguir las actuaciones salvo informe preceptivo, en cuyo caso se puede suspender (22.1.d).","note":"Informes «F-NV-10»: Facultativos, No Vinculantes, 10 días. Si no llega un informe PRECEPTIVO, se puede suspender el plazo de resolver (máximo 3 meses, art. 22).","pr":"B","n":4,"ex":4,"sub":0},{"law":"lbrl","art":"3","t":"Artículo 3.","mat":"Clases de entidades locales","cl":"Territoriales: municipio, provincia, isla. Además: comarcas, áreas metropolitanas, mancomunidades.","note":"Territoriales «M-P-I»: Municipio, Provincia, Isla (Baleares y Canarias). También locales: «CO-AM-MAN»: COmarcas, Áreas Metropolitanas, MANcomunidades de municipios.","pr":"B","n":4,"ex":4,"sub":0},{"law":"lpac","art":"98","t":"Artículo 98. Ejecutoriedad.","mat":"Ejecutoriedad","cl":"Actos inmediatamente ejecutivos salvo: suspensión, sanción contra la que quepa recurso administrativo (incluido el potestativo de reposición), disposición en contrario o aprobación superior. Pagos a la Administración: preferentemente electrónicos.","note":"Ejecutoriedad «NO se ejecuta si: SUSPENDIDO · SANCIÓN recurrible en vía administrativa · lo diga una norma · necesita APROBACIÓN superior». Pagos: electrónicos (tarjeta, transferencia, domiciliación…).","pr":"B","n":4,"ex":4,"sub":0},{"law":"ce","art":"142","t":"Artículo 142","mat":"Haciendas locales","cl":"Medios suficientes; tributos propios y participación en los del Estado y CCAA.","note":"Haciendas locales: medios SUFICIENTES; se nutren FUNDAMENTALMENTE de tributos propios y de la participación en los del Estado y de las CCAA.","pr":"B","n":4,"ex":4,"sub":0},{"law":"ce","art":"9","t":"Artículo 9","mat":"Principios garantizados (9.3)","cl":"7 principios: legalidad, jerarquía, publicidad, irretroactividad, seguridad jurídica, responsabilidad, interdicción de la arbitrariedad.","note":"9.3 = «LE-JE-PU-IRRE-SE-RE-IN» (7 principios): LEgalidad, JErarquía normativa, PUblicidad de las normas, IRREtroactividad de las sancionadoras no favorables o restrictivas, SEguridad jurídica, REsponsabilidad e INterdicción de la arbitrariedad de los poderes públicos. Ojo: la «eficacia» NO está (es del art. 103).","pr":"B","n":4,"ex":3,"sub":0},{"law":"ce","art":"31","t":"Artículo 31","mat":"Sistema tributario","cl":"Todos contribuyen según su capacidad económica; sistema tributario justo, igualdad y progresividad, nunca confiscatorio.","note":"«Todos (no sólo españoles) pagan según CAPACIDAD; justo, IGUAL, PROGRESIVO y NO confiscatorio». Prestaciones públicas sólo con arreglo a la ley.","pr":"B","n":3,"ex":3,"sub":1},{"law":"lprevencion","art":"21","t":"Artículo 21. Riesgo grave e inminente.","mat":"Riesgo grave e inminente","cl":"Interrumpir y abandonar; comunicación en 24 horas.","note":"Riesgo grave e inminente: informar, adoptar medidas, permitir interrumpir y abandonar. Si el empresario no actúa: paralización por mayoría de los representantes (o de los delegados de prevención si urge) → autoridad laboral anula o ratifica en 24 h. Sin perjuicio salvo mala fe o negligencia grave.","pr":"B","n":2,"ex":2,"sub":2},{"law":"rople","art":"23","t":"Artículo 23. Sesiones extraordinarias.","mat":"Debate del estado de la ciudad","cl":"Sesión extraordinaria; al menos dos veces por mandato; fecha fijada por la Alcaldía a propuesta de la Junta de Portavoces.","note":"«Estado de la ciudad = EXTRAordinaria, DOS por mandato».","pr":"B","n":0,"ex":0,"sub":0},{"law":"rople","art":"28","t":"Artículo 28. Especial consideración de las sesiones extraordinarias a solicitud de los miembros corporativos.","mat":"Sesión extraordinaria a petición de concejales","cl":"Al menos la cuarta parte del número legal; petición firmada en el Registro de la Secretaría General del Pleno.","note":"«1/4 lo pide, por escrito y firmado, en el registro del Pleno».","pr":"B","n":0,"ex":0,"sub":0},{"law":"rople","art":"38","t":"Artículo 38. Mociones no resolutivas.","mat":"Mociones no resolutivas","cl":"Por escrito en el Registro del Pleno con 5 días de antelación (sin contar el de presentación ni el de la sesión).","note":"«Mociones: 5 días antes».","pr":"B","n":0,"ex":0,"sub":0},{"law":"rople","art":"44","t":"Artículo 44. Ruegos Ruego es la formulación de una petición dirigida al equipo de gobierno o a un miembro del mismo, en relación con una actuación concreta. Todos los miembros de la corporación pueden presentar ruegos en el Pleno, oralmente o por escrito.","mat":"Ruegos","cl":"Por escrito, 72 horas antes del inicio de la sesión.","note":"«Ruegos: 72 horas».","pr":"B","n":0,"ex":0,"sub":0},{"law":"rople","art":"57","t":"Artículo 57. Enmiendas.","mat":"Enmiendas","cl":"Por escrito en el Registro del Pleno el día antes de la sesión; adición, supresión o reemplazo.","note":"«Enmienda = día ANTES».","pr":"B","n":0,"ex":0,"sub":0},{"law":"rople","art":"50","t":"Artículo 50. Constitución válida del Pleno.","mat":"Constitución válida y ausencias","cl":"La Secretaría comprueba el quórum, que debe mantenerse; quien no está al votar se entiende que se abstiene.","note":"«Fuera del salón al votar = ABSTENCIÓN».","pr":"B","n":0,"ex":0,"sub":0},{"law":"rople","art":"18","t":"Artículo 18. Constitución 1.","mat":"Junta de Portavoces","cl":"Alcaldía o presidencia y portavoces de los grupos; asistida por la Secretaría General del Pleno; órgano consultivo y deliberante.","note":"«Portavoces: CONSULTA, no decide»; los sustituye la portavocía adjunta.","pr":"B","n":0,"ex":0,"sub":0},{"law":"roga","art":"27","t":"Artículo 27. Certificación de los acuerdos.","mat":"Certificación de los acuerdos","cl":"Corresponde al Concejal Secretario.","note":"Ver la nota del art. 25.","pr":"B","n":0,"ex":0,"sub":0},{"law":"roga","art":"12","t":"Artículo 12. Suplencia del Alcalde.","mat":"Suplencia del Alcalde","cl":"Tenientes de Alcalde por orden de nombramiento, sin acto expreso.","note":"«Suplencia AUTOMÁTICA por orden de nombramiento».","pr":"B","n":0,"ex":0,"sub":0},{"law":"postal","art":"23","t":"Artículo 23. Condiciones de recogida y admisión de los envíos postales.","mat":"Recogida de envíos","cl":"Al menos una recogida todos los días laborables de lunes a viernes, incluso en zonas rurales.","note":"«Recoge y reparte de LUNES a VIERNES».","pr":"B","n":1,"ex":1,"sub":1},{"law":"postal","art":"24","t":"Artículo 24. Condiciones de distribución y entrega de los envíos postales.","mat":"Entrega de envíos","cl":"En la dirección de la cubierta; al menos todos los días laborables de lunes a viernes; casilleros domiciliarios.","note":"Ver la nota del art. 23.","pr":"B","n":0,"ex":0,"sub":0},{"law":"postal","art":"20","t":"Artículo 20. Concepto.","mat":"Concepto de servicio postal universal","cl":"Calidad determinada, régimen ordinario y permanente, todo el territorio y precio asequible.","note":"«Universal = TODO el territorio, SIEMPRE y ASEQUIBLE».","pr":"B","n":0,"ex":0,"sub":0},{"law":"rd203","art":"9","t":"Artículo 9. Sedes electrónicas de las Administraciones Públicas.","mat":"Sede electrónica","cl":"Dirección electrónica de titularidad pública para trámites con garantías.","note":"«Portal INFORMA, sede TRAMITA».","pr":"B","n":0,"ex":0,"sub":0},{"law":"lbrl","art":"69","t":"Artículo 69.","mat":"Información y participación ciudadana","cl":"Información en formatos accesibles y con diseño universal (reforma de 23/10/2026).","note":"🆕 «ACCESIBLE y para TODOS»: novedad legislativa de 2026.","pr":"B","n":0,"ex":0,"sub":0},{"law":"lprevencion","art":"23","t":"Artículo 23. Documentación.","mat":"Documentación preventiva","cl":"El empresario elabora y conserva el plan de prevención, la evaluación de riesgos, la planificación preventiva, los controles de salud y la relación de accidentes y enfermedades profesionales.","note":"«Papeles del empresario»: plan, evaluación, planificación, controles de salud y accidentes con baja de más de un día.","pr":"C","n":2,"ex":2,"sub":2},{"law":"escv","art":"22","t":"Artículo 22.","mat":"Funciones de Les Corts","cl":"Potestad legislativa, presupuestos, control del Consell, elección del President, designación de senadores…","note":"Les Corts «LEGISLAN, PRESUPUESTAN, CONTROLAN y ELIGEN» (al President y a los senadores autonómicos).","pr":"C","n":3,"ex":3,"sub":2},{"law":"lprevencion","art":"19","t":"Artículo 19. Formación de los trabajadores.","mat":"Formación de los trabajadores","cl":"Teórica y práctica, suficiente y adecuada, en la contratación y al cambiar de funciones o equipos; dentro de la jornada y sin coste.","note":"«Formación: al ENTRAR y al CAMBIAR; DENTRO de la jornada; GRATIS para el trabajador».","pr":"C","n":3,"ex":3,"sub":2},{"law":"lbrl","art":"22","t":"Artículo 22.","mat":"Pleno","cl":"Atribuciones 22.2; delegables e indelegables 22.4.","note":"Pleno = todos los Concejales, presidido por el Alcalde. Atribuciones «CONTROL-ORGANIZACIÓN-NORMAS-DINERO»: control de los órganos de gobierno, alteración del término, bandera, ordenanzas y reglamentos, presupuesto, plantilla y RPT, acciones judiciales en sus materias, cuestión de confianza. Indelegables las del 22.4 (salvo las delegables en el Alcalde y la JGL).","pr":"C","n":4,"ex":4,"sub":0},{"law":"lpac","art":"64","t":"Artículo 64. Acuerdo de iniciación en los procedimientos de naturaleza sancionadora.","mat":"Acuerdo de iniciación sancionador","cl":"Notificado al inculpado; contenido: responsables, hechos y posible sanción, instructor y secretario con régimen de recusación, órgano competente y posibilidad de reconocimiento voluntario, medidas provisionales, derecho a alegar. Si no alega, puede ser propuesta de resolución.","note":"Si no alega en plazo → el acuerdo de iniciación vale como PROPUESTA de resolución (cuando contenga un pronunciamiento preciso sobre la responsabilidad). Si faltan datos para calificar: PLIEGO DE CARGOS posterior.","pr":"C","n":4,"ex":3,"sub":0},{"law":"lo3","art":"10","t":"Artículo 10. Consecuencias jurídicas de las conductas discriminatorias.","mat":"Consecuencias jurídicas","cl":"Nulos y sin efecto; reparaciones reales, efectivas y proporcionadas.","note":"Consecuencias: «NULO + REPARO + DISUADO»: el acto discriminatorio es nulo y sin efecto; reparaciones reales, efectivas y proporcionadas; sanciones eficaces y disuasorias.","pr":"C","n":3,"ex":3,"sub":1},{"law":"lpac","art":"44","t":"Artículo 44. Notificación infructuosa.","mat":"Notificación infructuosa","cl":"Interesados desconocidos, lugar ignorado o intento fallido: anuncio en el BOE (Tablón Edictal Único). Previamente y de forma facultativa, en boletines de la CCAA o provincia, tablón del Ayuntamiento del último domicilio o consulado.","note":"Infructuosa → BOE SIEMPRE (Tablón Edictal Único). Lo demás (boletín autonómico o provincial, tablón municipal, consulado) es FACULTATIVO y complementario.","pr":"C","n":3,"ex":3,"sub":1},{"law":"escv","art":"20","t":"Artículo 20.","mat":"Instituciones","cl":"Corts, President, Consell + Sindicatura, Síndic, CVC, AVL, CJC, CES.","note":"Generalitat = «CORTS-PRESIDENT-CONSELL». Otras instituciones «SiSiCuAcaJuCES»: Sindicatura de Comptes, Síndic de Greuges, Consell Valencià de Cultura, Acadèmia Valenciana de la Llengua, Consell Jurídic Consultiu y Comité Econòmic i Social.","pr":"C","n":4,"ex":4,"sub":1},{"law":"lpac","art":"121","t":"Artículo 121. Objeto.","mat":"Recurso de alzada: objeto","cl":"Contra resoluciones y actos de trámite cualificados que NO pongan fin a la vía administrativa; ante el superior jerárquico; se puede presentar ante el que dictó el acto o el competente. Tribunales de selección: ante el órgano al que estén adscritos o, en su defecto, el que nombró a su presidente.","note":"Alzada = acto que NO agota la vía + al SUPERIOR. Tribunales y órganos de selección: dependen del órgano al que estén ADSCRITOS o, en su defecto, del que NOMBRÓ a su presidente.","pr":"C","n":3,"ex":3,"sub":0},{"law":"lo3","art":"1","t":"Artículo 1. Objeto de la Ley.","mat":"Objeto","cl":"Iguales en dignidad, derechos y deberes.","note":"Objeto de la LO 3/2007: igualdad de trato y de oportunidades, en desarrollo de los arts. 9.2 y 14 CE, en las esferas «PoCiLaEcoSoCu» (política, civil, laboral, económica, social y cultural), para una sociedad más democrática, justa y solidaria. Se aplica a toda persona física o jurídica que se encuentre o actúe en territorio español.","pr":"C","n":3,"ex":3,"sub":0},{"law":"ce","art":"10","t":"Artículo 10","mat":"Dignidad e interpretación","cl":"Interpretación conforme a la Declaración Universal y a los tratados ratificados.","note":"Fundamento del orden político «DIDELI-RES»: Dignidad, Derechos inviolables, Libre desarrollo de la personalidad, Respeto a la ley y a los derechos de los demás. Los derechos se interpretan conforme a la Declaración Universal de Derechos Humanos y los tratados ratificados.","pr":"C","n":3,"ex":2,"sub":0},{"law":"lbrl","art":"19","t":"Artículo 19.","mat":"Gobierno municipal","cl":"Ayuntamiento: Alcalde y Concejales.","note":"Gobierno municipal: el AYUNTAMIENTO (Alcalde y Concejales), salvo en el Concejo Abierto. Concejales por sufragio; Alcalde por los concejales o por los vecinos. Los municipios de gran población se rigen por el Título X.","pr":"C","n":3,"ex":2,"sub":0},{"law":"lpac","art":"76","t":"Artículo 76. Alegaciones.","mat":"Alegaciones","cl":"Los interesados pueden aducir alegaciones y aportar documentos en cualquier momento anterior al trámite de audiencia; se tienen en cuenta en la propuesta de resolución.","note":"Alegar: en CUALQUIER momento ANTES de la audiencia. Los defectos de tramitación (paralización, infracción de plazos) se pueden alegar siempre.","pr":"C","n":3,"ex":3,"sub":0},{"law":"lpac","art":"50","t":"Artículo 50. Conversión de actos viciados.","mat":"Conversión de actos viciados","cl":"Los actos nulos o anulables que contengan los elementos constitutivos de otro distinto producirán los efectos de este.","note":"Conversión: el acto viciado «se convierte» en el acto válido cuyos elementos contiene. Sirve para nulos Y anulables.","pr":"C","n":3,"ex":3,"sub":0},{"law":"lpac","art":"124","t":"Artículo 124. Plazos.","mat":"Recurso de reposición: plazos","cl":"Acto expreso: 1 mes; si no es expreso, en cualquier momento desde el día siguiente al silencio. Resolver y notificar: 1 mes. No cabe nuevo recurso de reposición contra su resolución.","note":"⚠ Artículo modificado (recientemente): comprueba el texto vigente. Reposición «1-1»: 1 MES para interponer, 1 MES para resolver. Nada de reposición sobre reposición.","pr":"C","n":3,"ex":3,"sub":0},{"law":"lo3","art":"7","t":"Artículo 7. Acoso sexual y acoso por razón de sexo.","mat":"Acoso sexual y por razón de sexo","cl":"Distinguir: «de naturaleza sexual» / «en función del sexo».","note":"Acoso SEXUAL = comportamiento «de naturaleza sexual». Acoso POR RAZÓN DE SEXO = comportamiento «en función del sexo». Ambos: atentan contra la dignidad, entorno intimidatorio, degradante u ofensivo. Ambos son discriminatorios.","pr":"C","n":3,"ex":3,"sub":0},{"law":"ce","art":"16","t":"Artículo 16","mat":"Libertad ideológica y religiosa","cl":"Nadie está obligado a declarar sobre su ideología, religión o creencias; ninguna confesión tendrá carácter estatal; cooperación con la Iglesia Católica y demás confesiones.","note":"«Aconfesional, no laico»: ninguna confesión estatal, pero COOPERACIÓN con la Católica Y las demás.","pr":"C","n":3,"ex":3,"sub":0},{"law":"lbrl","art":"127","t":"Artículo 127. Atribuciones de la Junta de Gobierno Local.","mat":"Junta de Gobierno Local en gran población","cl":"Atribuciones: aprobar proyectos de ordenanzas y presupuesto, licencias, contratación, personal…","note":"La JGL de gran población APRUEBA PROYECTOS (los aprueba el Pleno después) y GESTIONA: licencias, contratos, personal, patrimonio.","pr":"C","n":3,"ex":3,"sub":0},{"law":"lbrl","art":"13","t":"Artículo 13.","mat":"Creación de municipios","cl":"Núcleos diferenciados de al menos 4.000 habitantes (no 5.000).","note":"⚠ Artículo modificado (21/12/2023): comprueba el texto vigente. «4.000, no 5.000»: para segregar y crear municipio hacen falta núcleos de población territorialmente diferenciados de al menos 4.000 habitantes. Truco: 4 patas = un municipio que se sostiene. Además, el nuevo y el de origen deben ser financieramente sostenibles, sin merma de la calidad del servicio.","pr":"C","n":3,"ex":3,"sub":0},{"law":"lpac","art":"54","t":"Artículo 54. Clases de iniciación.","mat":"Clases de iniciación","cl":"De oficio o a solicitud del interesado.","note":"Dos puertas: OFICIO o SOLICITUD.","pr":"C","n":3,"ex":3,"sub":0},{"law":"lpac","art":"109","t":"Artículo 109. Revocación de actos y rectificación de errores.","mat":"Revocación y rectificación de errores","cl":"Revocar actos de gravamen o desfavorables mientras no haya prescrito, si no es dispensa no permitida ni contraria a igualdad o interés público. Rectificar errores materiales, de hecho o aritméticos en cualquier momento.","note":"Revocación: solo actos DESFAVORABLES, mientras no PRESCRIBA. Rectificación de errores materiales, de hecho o aritméticos: en CUALQUIER momento.","pr":"C","n":3,"ex":3,"sub":0},{"law":"lpac","art":"62","t":"Artículo 62. Inicio del procedimiento por denuncia.","mat":"Denuncia","cl":"Pone en conocimiento hechos que pueden justificar la iniciación de oficio. Identidad del denunciante y relato. Exención al primero que aporte pruebas si participó (clemencia). No confiere por sí sola la condición de interesado.","note":"Denunciante ≠ interesado. Si participó en la infracción y es el PRIMERO en aportar pruebas → EXENCIÓN; si no es el primero pero aporta valor añadido → REDUCCIÓN. En ambos casos debe cesar en la infracción y no haber destruido pruebas.","pr":"C","n":3,"ex":3,"sub":0},{"law":"ce","art":"53","t":"Artículo 53","mat":"Garantías","cl":"53.2: preferencia y sumariedad + amparo para art. 14, Sección 1.ª y objeción de conciencia (art. 30).","note":"Garantías «53.1 ley-contenido esencial; 53.2 preferente, sumario y amparo (art. 14, Sección 1.ª y objeción del art. 30); 53.3 principios rectores que informan la legislación y solo se alegan conforme a sus leyes».","pr":"C","n":3,"ex":3,"sub":0},{"law":"lpac","art":"70","t":"Artículo 70. Expediente Administrativo.","mat":"Expediente administrativo","cl":"Conjunto ordenado de documentos y actuaciones que sirven de antecedente y fundamento a la resolución y diligencias de ejecución. Formato electrónico, índice numerado. No forman parte: información auxiliar o de apoyo (notas, borradores, opiniones, resúmenes, informes internos).","note":"Expediente: electrónico, ordenado y con ÍNDICE numerado. NO incluye borradores, notas, opiniones ni informes internos, salvo los informes (preceptivos o facultativos) pedidos antes de la resolución.","pr":"C","n":3,"ex":3,"sub":0},{"law":"ce","art":"154","t":"Artículo 154","mat":"Delegado del Gobierno","cl":"Dirige la Administración del Estado en el territorio de la CA y la coordina con la autonómica.","note":"«154 = Delegado del Gobierno»: lo nombra el Gobierno. No confundir con el President de la Generalitat (152).","pr":"C","n":2,"ex":2,"sub":1},{"law":"lpac","art":"102","t":"Artículo 102. Ejecución subsidiaria.","mat":"Ejecución subsidiaria","cl":"Actos no personalísimos que puede realizar otro; por la Administración o personas que designe, a costa del obligado; liquidación provisional y cobro anticipado.","note":"Ejecución subsidiaria = lo hace OTRO (no personalísimo) y lo PAGA el obligado (se puede cobrar por anticipado).","pr":"C","n":3,"ex":3,"sub":0},{"law":"lpac","art":"49","t":"Artículo 49. Límites a la extensión de la nulidad o anulabilidad de los actos.","mat":"Límites a la extensión de la nulidad","cl":"La nulidad de un acto no implica la de los sucesivos independientes; la de una parte no afecta a las demás independientes salvo que sin ella no se hubiera dictado.","note":"«La manzana podrida no pudre el cesto»: la nulidad no se extiende a los actos o partes INDEPENDIENTES.","pr":"C","n":3,"ex":3,"sub":0},{"law":"ce","art":"15","t":"Artículo 15","mat":"Derecho a la vida","cl":"Todos tienen derecho a la vida y a la integridad; abolida la pena de muerte; prohibidas la tortura y las penas o tratos inhumanos.","note":"«15 = vida»: TODOS (no sólo españoles). Pena de muerte abolida (reforma de la LO 11/1995 sobre leyes penales militares).","pr":"C","n":2,"ex":2,"sub":1},{"law":"escv","art":"28","t":"Artículo 28.","mat":"Censura y disolución","cl":"Moción: mayoría absoluta y 1/5 de diputados; 5 días.","note":"Moción de censura en Les Corts: «1/5 la propone, absoluta la aprueba, con candidato». El President dirige el Consell, ostenta la más alta representación de la Comunitat y la ordinaria del Estado; responde ante Les Corts.","pr":"C","n":2,"ex":2,"sub":2},{"law":"lprevencion","art":"26","t":"Artículo 26. Protección de la maternidad.","mat":"Protección de la maternidad","cl":"Adaptación de condiciones o del turno; cambio de puesto; suspensión por riesgo durante el embarazo y la lactancia.","note":"Embarazo: «ADAPTAR → CAMBIAR de puesto → SUSPENDER» (riesgo durante el embarazo o la lactancia natural).","pr":"C","n":2,"ex":2,"sub":2},{"law":"lpac","art":"63","t":"Artículo 63. Especialidades en el inicio de los procedimientos de naturaleza sancionadora.","mat":"Especialidades en el inicio del sancionador","cl":"Siempre de oficio; separación entre fase instructora y sancionadora (órganos distintos); no se puede sancionar sin procedimiento; infracción continuada: no nuevos procedimientos mientras no haya una primera resolución sancionadora ejecutiva.","note":"Sancionador: SIEMPRE de oficio. Quien instruye NO resuelve. Sin procedimiento NO hay sanción.","pr":"C","n":3,"ex":3,"sub":0},{"law":"lpac","art":"90","t":"Artículo 90. Especialidades de la resolución en los procedimientos sancionadores.","mat":"Resolución en sancionadores","cl":"Valoración de pruebas, hechos, responsables, infracción y sanción. No hechos distintos de los del procedimiento. Mayor gravedad: 15 días de alegaciones. Ejecutiva cuando no quepa recurso ordinario en vía administrativa. Suspensión cautelar si anuncia contencioso.","note":"Sanción: ejecutiva solo cuando NO cabe recurso ORDINARIO en vía administrativa. Si el órgano ve más gravedad que la propuesta: 15 días al inculpado.","pr":"C","n":3,"ex":3,"sub":0},{"law":"rof","art":"82","t":"Artículo 82.","mat":"Orden del día del Pleno","cl":"Lo fija el Alcalde, asistido por el Secretario; puede consultar a los portavoces; los asuntos deben estar dictaminados.","note":"Orden del día: lo FIJA el Alcalde con el Secretario. En Gandia la Junta de Portavoces debe ser OÍDA (art. 20 ROPLE).","pr":"C","n":3,"ex":3,"sub":0},{"law":"escv","art":"25","t":"Artículo 25.","mat":"Funcionamiento","cl":"Reglamento por mayoría absoluta; leyes de bases y presupuestos no delegables; 2 periodos, mín. 8 meses.","note":"⚠ Artículo modificado (recientemente): comprueba el texto vigente. Les Corts: Reglamento por MAYORÍA ABSOLUTA; eligen Presidente, Mesa y Diputación Permanente; funcionan en Pleno y Comisiones; NO delegables en Comisión: reforma del Estatuto, leyes de bases, presupuestos e instituciones (las de mayoría cualificada).","pr":"C","n":2,"ex":2,"sub":1},{"law":"escv","art":"1","t":"Artículo 1.","mat":"La Comunitat Valenciana","cl":"Nacionalidad histórica; autogobierno; reforzar la democracia y garantizar la participación.","note":"«Nacionalidad HISTÓRICA». Objetivo: autogobierno, reforzar la DEMOCRACIA y garantizar la PARTICIPACIÓN.","pr":"C","n":2,"ex":2,"sub":1},{"law":"rople","art":"77","t":"Artículo 77. Ruegos y preguntas en comisión.","mat":"Ruegos y preguntas en comisión","cl":"En el Registro del Pleno con 24 horas de antelación.","note":"«Comisión: 24 horas» (Pleno: 72 horas los ruegos).","pr":"C","n":0,"ex":0,"sub":0},{"law":"rople","art":"15","t":"Artículo 15. Secretario/a general del Pleno.","mat":"Secretaría General del Pleno","cl":"Funcionario con habilitación de carácter nacional; registro propio del Pleno.","note":"«Pleno con SECRETARIO propio y REGISTRO propio».","pr":"C","n":0,"ex":0,"sub":0},{"law":"roga","art":"32","t":"Artículo 32. Responsabilidad política.","mat":"Responsabilidad política de la Junta","cl":"Solidaria ante el Pleno, más la directa de cada miembro; exigible mediante moción de censura y cuestión de confianza.","note":"«SOLIDARIA ante el Pleno».","pr":"C","n":0,"ex":0,"sub":0},{"law":"postal","art":"33","t":"Artículo 33. Garantías.","mat":"Garantías del operador designado","cl":"Uso exclusivo de «Correos» y de su emblema (cornamusa con corona), buzones en dominio público…","note":"«Correos + cornamusa con corona».","pr":"C","n":0,"ex":0,"sub":0}];
